// Secure Express app with basic security practices (no external dependencies)
const express = require('express');
const app = express();

// Basic security middleware
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// Basic rate limiting
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = 100;

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { count: 1, startTime: now });
  } else {
    const ipData = requestCounts.get(ip);
    if (now - ipData.startTime > windowMs) {
      // Reset counter if window has passed
      requestCounts.set(ip, { count: 1, startTime: now });
    } else if (ipData.count >= maxRequests) {
      return res.status(429).json({ 
        error: 'Too many requests', 
        message: 'Please try again later.' 
      });
    } else {
      ipData.count++;
    }
  }
  next();
});

// Input validation helper
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateInteger = (value, min = 1, max = Infinity) => {
  const num = parseInt(value, 10);
  return !isNaN(num) && num >= min && num <= max;
};

// Enhanced health endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable' 
    });
  }
});

// Enhanced users endpoint with validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page = '1', limit = '10' } = req.query;

    if (!validateInteger(page, 1) || !validateInteger(limit, 1, 100)) {
      return res.status(400).json({
        error: 'Invalid parameters',
        message: 'Page and limit must be positive integers. Limit max: 100'
      });
    }

    // Safe data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// Create user endpoint with validation
app.post('/users', express.json({ limit: '10kb' }), (req, res) => {
  try {
    const { name, email, password } = req.body || {};

    // Input validation
    const errors = [];

    if (!name || typeof name !== 'string' || name.trim().length < 2) {
      errors.push('Name must be at least 2 characters long');
    }

    if (!email || !validateEmail(email)) {
      errors.push('Valid email is required');
    }

    if (!password || typeof password !== 'string' || password.length < 8) {
      errors.push('Password must be at least 8 characters long');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        success: false,
        errors: errors
      });
    }

    // Sanitize inputs
    const sanitizedName = name.trim();
    const sanitizedEmail = email.toLowerCase().trim();

    // In real app: hash password, store in database
    const newUser = {
      id: Date.now(),
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({
      success: false,
      message: 'Failed to create user'
    });
  }
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);
  res.status(500).json({
    success: false,
    message: 'An unexpected error occurred'
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});

module.exports = app;

