// Enhanced Express.js application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const logger = require('./logger'); // Assuming you create a logger module

const app = express();

// ================= SECURITY MIDDLEWARE =================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false
}));

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting (prevent DDoS/brute force attacks)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - IP: ${req.ip} - User-Agent: ${req.get('User-Agent')}`);
  next();
});

// ================= VALIDATION MIDDLEWARE =================

const validateUserInput = [
  body('name').isLength({ min: 1, max: 50 }).trim().escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid input data',
        details: errors.array()
      });
    }
    next();
  }
];

// ================= ROUTES WITH IMPROVED ERROR HANDLING =================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      status: 'error'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', async (req, res, next) => {
  try {
    // Validate query parameters if any
    const { page = 1, limit = 10 } = req.query;

    // Input validation for numeric parameters
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    if (isNaN(pageNum) || pageNum < 1 || isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: 'page and limit must be positive integers, limit max 100'
      });
    }

    // Simulate database call with error handling
    const users = await getUsersFromDatabase(pageNum, limitNum);

    res.json({
      users,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length
      }
    });

  } catch (error) {
    logger.error('Users endpoint error:', error);
    next(error); // Pass to error handling middleware
  }
});

// POST endpoint example with validation
app.post('/users', validateUserInput, async (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Additional business logic validation
    if (/\.\./.test(name)) {
      return res.status(400).json({
        error: 'Invalid name format',
        message: 'Name contains invalid characters'
      });
    }

    // Simulate user creation
    const newUser = await createUser({ name, email });

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });

  } catch (error) {
    if (error.code === 'DUPLICATE_EMAIL') {
      return res.status(409).json({
        error: 'Duplicate email',
        message: 'A user with this email already exists'
      });
    }
    logger.error('Create user error:', error);
    next(error);
  }
});

// ================= ERROR HANDLING MIDDLEWARE =================

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', error);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { 
        error: 'Internal Server Error',
        message: 'Something went wrong. Please try again later.'
      }
    : {
        error: error.message,
        stack: error.stack,
        ...error
      };

  res.status(error.status || 500).json(errorResponse);
});

// ================= UTILITY FUNCTIONS =================

async function getUsersFromDatabase(page, limit) {
  // In a real application, this would be a database call
  // For demo purposes, return static data with pagination simulation
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
  ];

  const startIndex = (page - 1) * limit;
  return allUsers.slice(startIndex, startIndex + limit);
}

async function createUser(userData) {
  // In a real application, this would create a user in the database
  // Simulate async operation and potential errors
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (userData.email === 'duplicate@example.com') {
        const error = new Error('Email already exists');
        error.code = 'DUPLICATE_EMAIL';
        reject(error);
      } else {
        resolve({
          id: Math.floor(Math.random() * 1000),
          ...userData,
          createdAt: new Date().toISOString()
        });
      }
    }, 100);
  });
}

// ================= SERVER STARTUP =================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

module.exports = app;

// Simple logger module
const logger = {
  info: (message, meta = {}) => {
    console.log(`[INFO] ${new Date().toISOString()}: ${message}`, meta);
  },

  error: (message, error = null, meta = {}) => {
    console.error(`[ERROR] ${new Date().toISOString()}: ${message}`);
    if (error) {
      console.error('Error details:', error.stack || error);
    }
    if (Object.keys(meta).length > 0) {
      console.error('Meta:', meta);
    }
  },

  warn: (message, meta = {}) => {
    console.warn(`[WARN] ${new Date().toISOString()}: ${message}`, meta);
  },

  debug: (message, meta = {}) => {
    if (process.env.NODE_ENV !== 'production') {
      console.debug(`[DEBUG] ${new Date().toISOString()}: ${message}`, meta);
    }
  }
};

module.exports = logger;

