const { body, validationResult } = require('express-validator');

// Validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Health endpoint validation
const healthValidation = [
  body('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
];

// Users endpoint validation  
const usersValidation = [
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
];

module.exports = {
  validateInput,
  healthValidation,
  usersValidation
};

// Comprehensive error handling patterns

// Global error handler
const errorHandler = (error, req, res, next) => {
  console.error('Error:', {
    message: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors in production
  const errorResponse = process.env.NODE_ENV === 'development' 
    ? { error: error.message }
    : { error: 'Internal server error' };

  res.status(error.status || 500).json(errorResponse);
};

// Async error wrapper (for async routes)
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Custom error classes
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.status = 400;
  }
}

class NotFoundError extends Error {
  constructor(message = 'Resource not found') {
    super(message);
    this.name = 'NotFoundError';
    this.status = 404;
  }
}

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({ error: 'Route not found' });
};

module.exports = {
  errorHandler,
  asyncHandler,
  ValidationError,
  NotFoundError,
  notFoundHandler
};

// Security middleware implementations
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Security headers with helmet
const securityHeaders = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false,
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});

// Request size limiting
const requestSizeLimit = (req, res, next) => {
  // Limit JSON payload to 10kb
  if (req.headers['content-length'] > 10240) {
    return res.status(413).json({ error: 'Payload too large' });
  }
  next();
};

// Input sanitization (basic example)
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    });
  }

  // Sanitize body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].replace(/[<>]/g, '');
      }
    });
  }

  next();
};

module.exports = {
  securityHeaders,
  limiter,
  requestSizeLimit,
  sanitizeInput
};

