// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' ? process.env.ALLOWED_ORIGINS || 'https://yourdomain.com' : '*',
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging
app.use(morgan('combined'));

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Enhanced health check with validation
app.get('/health', (req, res) => {
  const healthCheck = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development'
  };

  try {
    // Add any additional health checks here
    res.json(healthCheck);
  } catch (error) {
    res.status(503).json({ 
      status: 'error', 
      error: 'Service unavailable' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Parameter validation
    const { limit, offset } = req.query;

    if (limit && !/^\d+$/.test(limit)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be a positive integer.' 
      });
    }

    if (offset && !/^\d+$/.test(offset)) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter. Must be a positive integer.' 
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit if provided
    const result = limit ? users.slice(0, parseInt(limit)) : users;

    res.json(result);
  } catch (error) {
    next(error);
  }
});

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred',
    status: err.status || 500
  };

  res.status(errorResponse.status).json(errorResponse);
};

app.use(errorHandler);

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Route not found',
    path: req.originalUrl 
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000 in', process.env.NODE_ENV || 'development', 'mode');
});

module.exports = app;

