  res.setHeader('Cache-Control', 'no-store');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', asyncHandler(async (req, res) => {
  // Input validation and sanitization
  const { limit, offset } = req.query;

  // Validate and sanitize numeric parameters
  const validatedLimit = limit ? Math.min(Math.max(parseInt(limit) || 10, 1), 100) : 10;
  const validatedOffset = offset ? Math.max(parseInt(offset) || 0, 0) : 0;

  // Prevent sensitive data exposure by filtering response
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter out sensitive data for response
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name
    // Email intentionally omitted for security
  }));

  res.setHeader('Cache-Control', 'no-store');
  res.json({
    users: sanitizedUsers.slice(validatedOffset, validatedOffset + validatedLimit),
    pagination: {
      total: sanitizedUsers.length,
      limit: validatedLimit,
      offset: validatedOffset
    }
  });
}));

// Add security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// Error handler (must be last)
app.use(errorHandler);

// Environment-based configuration
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

