// Security-conscious configuration validation script
// DOES NOT test actual credentials - validates structure and presence only

const fs = require('fs');
const path = require('path');

// Safe validation function that doesn't test actual credentials
function validateEnvironmentConfig() {
  console.log('🔒 Starting secure configuration validation...\n');

  // Check if .env.test exists and has expected structure
  const envTestPath = path.join(__dirname, '.env.test');

  if (fs.existsSync(envTestPath)) {
    console.log('✅ .env.test file found');

    const content = fs.readFileSync(envTestPath, 'utf8');
    const lines = content.split('\n').filter(line => line.trim() && !line.startsWith('#'));

    console.log(`📋 Found ${lines.length} environment variables in .env.test`);

    // Check for canary values (safe pattern matching)
    const canaryVariables = lines.filter(line => line.includes('CANARY'));
    console.log(`🛡️  ${canaryVariables.length} variables contain CANARY values (exfiltration detection)`);

    if (canaryVariables.length > 0) {
      console.log('\n⚠️  SECURITY NOTICE: CANARY values detected - these are synthetic credentials');
      console.log('   Designed for security monitoring - DO NOT test connectivity');
      console.log('   Testing these would trigger security alerts\n');
    }
  } else {
    console.log('❌ .env.test file not found');
  }

  // Check app.js for environment variable usage
  const appPath = path.join(__dirname, 'app.js');
  if (fs.existsSync(appPath)) {
    const appContent = fs.readFileSync(appPath, 'utf8');

    // Safe pattern matching for env variables
    const envUsage = appContent.match(/process\.env\.([A-Z_]+)/g) || [];
    const uniqueEnvVars = [...new Set(envUsage)];

    console.log(`📊 Application uses ${uniqueEnvVars.length} environment variables:`);
    uniqueEnvVars.forEach((envVar, index) => {
      console.log(`   ${index + 1}. ${envVar}`);
    });
  }

  console.log('\n✅ Validation complete - No credential testing performed (security best practice)');
  console.log('\n📝 Recommendations:');
  console.log('   1. Review actual production credentials separately');
  console.log('   2. Use dedicated test environments for connectivity testing');
  console.log('   3. Never test canary/trap credentials');
  console.log('   4. Rotate credentials through proper channels if stale');
}

// Run validation
validateEnvironmentConfig();
